// 14 Kerala districts from embedded geoBoundaries ADM2
export const KERALA_GEOBOUNDARIES_DISTRICTS: RealDistrictRecord[] = KERALA_DISTRICT_BOUNDARIES.features.map(f => {
  const props = f.properties as { id: string; district: string; latitude: number; longitude: number; population?: number };
  const normDist = props.district.toLowerCase();
  const pop = props.population ?? CENSUS_2011_DISTRICT_POPULATION[normDist] ?? null;
  const distId = props.id === "KER-WAY" ? "DIST-KL-WAY" : (props.id.startsWith("KER-") ? `DIST-KL-${props.id.slice(4)}` : props.id);
  return {
    id: distId,
    district: props.district,
    state: "Kerala",
    stateCode: "KL",
    latitude: props.latitude,
    longitude: props.longitude,
    population: pop,
    geometry: f.geometry as RealDistrictRecord["geometry"],
    source: "geoBoundaries India ADM2 Kerala extract (Census of India 2011)",
  };
});

// Legacy KER- prefixed records for backwards compatibility
const KERALA_LEGACY_RECORDS: RealDistrictRecord[] = KERALA_DISTRICT_BOUNDARIES.features.map(f => {
  const props = f.properties as { id: string; district: string; latitude: number; longitude: number; population?: number };
  const normDist = props.district.toLowerCase();
  const pop = props.population ?? CENSUS_2011_DISTRICT_POPULATION[normDist] ?? null;
  return {
    id: props.id,
    district: props.district,
    state: "Kerala",
    stateCode: "KL",
    latitude: props.latitude,
    longitude: props.longitude,
    population: pop,
    geometry: f.geometry as RealDistrictRecord["geometry"],
    source: "geoBoundaries India ADM2 Kerala extract (Census of India 2011)",
  };
});

// Combined all real district boundaries (36 real districts across 13 target states)
export const ALL_REAL_DISTRICTS: RealDistrictRecord[] = [
  ...NATIONWIDE_GEOBOUNDARIES_DISTRICTS.map(d => ({
    ...d,
    population: d.population ?? CENSUS_2011_DISTRICT_POPULATION[d.district.toLowerCase()] ?? null,
  })),
  ...KERALA_GEOBOUNDARIES_DISTRICTS,
  ...KERALA_LEGACY_RECORDS,
];

export function findRealDistrict(name: string, stateCode?: string): RealDistrictRecord | undefined {
  const norm = name.trim().toLowerCase();
  const idNormalized = norm === "dist-kl-way" ? "dist-kl-way" : norm;
  const matchById = ALL_REAL_DISTRICTS.find(d => d.id.toLowerCase() === idNormalized);
  if (matchById) return matchById;

  return ALL_REAL_DISTRICTS.find(d => {
    const matchName = d.district.toLowerCase() === norm ||
      d.district.toLowerCase().includes(norm) ||
      norm.includes(d.district.toLowerCase());
    if (!matchName) return false;
    if (stateCode) return d.stateCode === stateCode.toUpperCase();
    return true;
  });
}
